-- The registry reads the subgraph makes with `contract.method(...)` inside a handler. Each is a
-- row-driven [[calls]] in nuthatch.toml, pinned to the block of the event that triggers it, and each
-- result is the raw ABI return in `result`, one 32-byte word per field. The views slice the words.
-- A uint256 word is turned into DECIMAL(38,0) from its low 32 hex digits (the high 32 are zero for
-- any fee that fits in 38 digits). Its expression is written out in full because the SQL surface
-- has no hex-to-number function; spike/gen-reads.py wrote it.

-- ModelRegistrationRequest: modelRequests(requestId) at the request's block, then ModelApproved or
-- ModelRejected marks it processed. `model_id` is set only on approval, as in the subgraph.
CREATE VIEW model_registration_requests AS
  WITH p AS (
    SELECT "requestId", 'approved' AS how, block_number, block_timestamp, log_index, "modelId_dec" AS model_id FROM registry__model_approved
    UNION ALL
    SELECT "requestId", 'rejected', block_number, block_timestamp, log_index, CAST(NULL AS DECIMAL(38, 0)) FROM registry__model_rejected
  ),
  lp AS (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY "requestId" ORDER BY block_number DESC, log_index DESC) AS rn FROM p
  )
  SELECT r."requestId_dec" AS request_id, r.requester,
         substr(c.result, 130, 1) = '1' AS is_open_source,
         CAST((strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 33, 1)) - 1) * CAST('21267647932558653966460912964485513216' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 34, 1)) - 1) * CAST('1329227995784915872903807060280344576' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 35, 1)) - 1) * CAST('83076749736557242056487941267521536' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 36, 1)) - 1) * CAST('5192296858534827628530496329220096' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 37, 1)) - 1) * CAST('324518553658426726783156020576256' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 38, 1)) - 1) * CAST('20282409603651670423947251286016' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 39, 1)) - 1) * CAST('1267650600228229401496703205376' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 40, 1)) - 1) * CAST('79228162514264337593543950336' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 41, 1)) - 1) * CAST('4951760157141521099596496896' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 42, 1)) - 1) * CAST('309485009821345068724781056' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 43, 1)) - 1) * CAST('19342813113834066795298816' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 44, 1)) - 1) * CAST('1208925819614629174706176' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 45, 1)) - 1) * CAST('75557863725914323419136' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 46, 1)) - 1) * CAST('4722366482869645213696' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 47, 1)) - 1) * CAST('295147905179352825856' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 48, 1)) - 1) * CAST('18446744073709551616' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 49, 1)) - 1) * CAST('1152921504606846976' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 50, 1)) - 1) * CAST('72057594037927936' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 51, 1)) - 1) * CAST('4503599627370496' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 52, 1)) - 1) * CAST('281474976710656' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 53, 1)) - 1) * CAST('17592186044416' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 54, 1)) - 1) * CAST('1099511627776' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 55, 1)) - 1) * CAST('68719476736' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 56, 1)) - 1) * CAST('4294967296' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 57, 1)) - 1) * CAST('268435456' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 58, 1)) - 1) * CAST('16777216' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 59, 1)) - 1) * CAST('1048576' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 60, 1)) - 1) * CAST('65536' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 61, 1)) - 1) * CAST('4096' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 62, 1)) - 1) * CAST('256' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 63, 1)) - 1) * CAST('16' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 323, 64), 64, 1)) - 1) * CAST('1' AS DECIMAL(38, 0)) AS DECIMAL(38, 0)) AS fee_paid,
         '0x' || substr(c.result, 131, 64) AS manifest_cid,
         '0x' || substr(c.result, 219, 40) AS task_coordinator,
         '0x' || substr(c.result, 283, 40) AS task_auditor,
         lp.how IS NOT NULL AS processed,
         CASE WHEN lp.how IS NOT NULL THEN lp.how = 'approved' END AS approved,
         lp.model_id,
         r.block_number AS submitted_at_block, to_timestamp(r.block_timestamp) AS submitted_at,
         lp.block_number AS processed_at_block, to_timestamp(lp.block_timestamp) AS processed_at
  FROM registry__model_registration_requested r
  JOIN model_request_record c ON c.block_number = r.block_number
   AND substr(c.calldata, 11) = lpad(to_hex(CAST(r."requestId_dec" AS BIGINT)), 64, '0')
  LEFT JOIN lp ON lp.rn = 1 AND lp."requestId" = r."requestId";

-- ManifestUpdateRequest: manifestRequests(requestId) at the request's block, then ManifestUpdated
-- or ManifestUpdateRejected marks it processed. The requester is the model's owner when the model
-- is known (only its owner can ask), else the transaction's sender, which this nest does not keep,
-- so it is NULL then.
CREATE VIEW manifest_update_requests AS
  WITH p AS (
    SELECT "requestId", 'approved' AS how, block_number, block_timestamp, log_index FROM registry__manifest_updated
    UNION ALL
    SELECT "requestId", 'rejected', block_number, block_timestamp, log_index FROM registry__manifest_update_rejected
  ),
  lp AS (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY "requestId" ORDER BY block_number DESC, log_index DESC) AS rn FROM p
  )
  SELECT r."requestId_dec" AS request_id, r."modelId_dec" AS model_id, m.owner AS requester,
         CAST((strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 33, 1)) - 1) * CAST('21267647932558653966460912964485513216' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 34, 1)) - 1) * CAST('1329227995784915872903807060280344576' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 35, 1)) - 1) * CAST('83076749736557242056487941267521536' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 36, 1)) - 1) * CAST('5192296858534827628530496329220096' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 37, 1)) - 1) * CAST('324518553658426726783156020576256' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 38, 1)) - 1) * CAST('20282409603651670423947251286016' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 39, 1)) - 1) * CAST('1267650600228229401496703205376' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 40, 1)) - 1) * CAST('79228162514264337593543950336' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 41, 1)) - 1) * CAST('4951760157141521099596496896' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 42, 1)) - 1) * CAST('309485009821345068724781056' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 43, 1)) - 1) * CAST('19342813113834066795298816' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 44, 1)) - 1) * CAST('1208925819614629174706176' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 45, 1)) - 1) * CAST('75557863725914323419136' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 46, 1)) - 1) * CAST('4722366482869645213696' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 47, 1)) - 1) * CAST('295147905179352825856' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 48, 1)) - 1) * CAST('18446744073709551616' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 49, 1)) - 1) * CAST('1152921504606846976' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 50, 1)) - 1) * CAST('72057594037927936' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 51, 1)) - 1) * CAST('4503599627370496' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 52, 1)) - 1) * CAST('281474976710656' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 53, 1)) - 1) * CAST('17592186044416' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 54, 1)) - 1) * CAST('1099511627776' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 55, 1)) - 1) * CAST('68719476736' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 56, 1)) - 1) * CAST('4294967296' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 57, 1)) - 1) * CAST('268435456' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 58, 1)) - 1) * CAST('16777216' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 59, 1)) - 1) * CAST('1048576' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 60, 1)) - 1) * CAST('65536' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 61, 1)) - 1) * CAST('4096' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 62, 1)) - 1) * CAST('256' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 63, 1)) - 1) * CAST('16' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(c.result, 195, 64), 64, 1)) - 1) * CAST('1' AS DECIMAL(38, 0)) AS DECIMAL(38, 0)) AS fee_paid,
         '0x' || substr(c.result, 67, 64) AS new_manifest_cid,
         lp.how IS NOT NULL AS processed,
         CASE WHEN lp.how IS NOT NULL THEN lp.how = 'approved' END AS approved,
         r.block_number AS submitted_at_block, to_timestamp(r.block_timestamp) AS submitted_at,
         lp.block_number AS processed_at_block, to_timestamp(lp.block_timestamp) AS processed_at
  FROM registry__manifest_update_requested r
  JOIN manifest_request_record c ON c.block_number = r.block_number
   AND substr(c.calldata, 11) = lpad(to_hex(CAST(r."requestId_dec" AS BIGINT)), 64, '0')
  LEFT JOIN models m ON m.model_id = r."modelId_dec"
  LEFT JOIN lp ON lp.rn = 1 AND lp."requestId" = r."requestId";

-- FeeSnapshot. The four single setters carry only their own new value, so the whole schedule comes
-- from the four getters, read at the event's block ("granular"; one table of calls per getter per
-- setter, fee_<getter>_on_<event>). FeesUpdated carries all four ("atomic").
CREATE VIEW fee_snapshots AS
  SELECT CAST((strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 33, 1)) - 1) * CAST('21267647932558653966460912964485513216' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 34, 1)) - 1) * CAST('1329227995784915872903807060280344576' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 35, 1)) - 1) * CAST('83076749736557242056487941267521536' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 36, 1)) - 1) * CAST('5192296858534827628530496329220096' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 37, 1)) - 1) * CAST('324518553658426726783156020576256' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 38, 1)) - 1) * CAST('20282409603651670423947251286016' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 39, 1)) - 1) * CAST('1267650600228229401496703205376' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 40, 1)) - 1) * CAST('79228162514264337593543950336' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 41, 1)) - 1) * CAST('4951760157141521099596496896' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 42, 1)) - 1) * CAST('309485009821345068724781056' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 43, 1)) - 1) * CAST('19342813113834066795298816' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 44, 1)) - 1) * CAST('1208925819614629174706176' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 45, 1)) - 1) * CAST('75557863725914323419136' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 46, 1)) - 1) * CAST('4722366482869645213696' AS DECIMAL(38, 0)) + (strpos('0123456789abcdef', substr(substr(a.result, 3, 64), 47, 1)) - 1) * CAST('295147905179352825856' AS DEC