  JOIN fee_pr_on_proprietary_update_fee b ON b.block_number = g.block_number
  JOIN fee_osu_on_proprietary_update_fee c ON c.block_number = g.block_number
  JOIN fee_pru_on_proprietary_update_fee d ON d.block_number = g.block_number
